INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22477$nota-0015$m22477$, $m22478$Training and Racing with a Power Meter.pdf$m22478$, $m22479$48$m22479$, $m22480$Power meters can be finicky and you will occasionally get an erroneous sample of data, which usually manifests itself as a massive power spike above and beyond any wattage you have ever been able to create.$m22480$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22481$nota-0015$m22481$, $m22482$Training and Racing with a Power Meter.pdf$m22482$, $m22483$48$m22483$, $m22484$if your power data was recorded as 213, 234, 242, 1,876, 254, 260, 267, simply changing 1,876 to 248 (splitting the difference between 242 and 254)... We have long emphasized the value of analyzing your best 5 seconds of power with regard to your neuromuscular ability, and this situation illustrates why—it ensures that you have an accurate sense of your true maximum power.$m22484$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m22485$nota-0015$m22485$, $m22486$nota-0014$m22486$, $m22487$complementa$m22487$, $m22488$ambas tratam de erro/artefato de medição de potência; 0014 é erro sistemático (toda a atividade deslocada), 0015 é erro pontual (amostra única)$m22488$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22489$nota-0016$m22489$, $m22490$Training and Racing with a Power Meter.pdf$m22490$, $m22491$49$m22491$, $m22492$Any time you are not pedaling, your power meter will record zero watts—this is an important metric to understand... when analyzing cadence it's important to not average the time spent not pedaling.$m22492$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22493$nota-0016$m22493$, $m22494$Training and Racing with a Power Meter.pdf$m22494$, $m22495$49$m22495$, $m22496$let's say you are riding a 5-minute interval at 90 rpm and 3 minutes into the effort you have to ride down a steep, but short and technical hill, so you coast for a little bit... if you include that zero cadence then your average rpm would be 81 rpm, which would be misleading.$m22496$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22497$nota-0018$m22497$, $m22498$Training and Racing with a Power Meter.pdf$m22498$, $m22499$35$m22499$, $m22500$there are five distinct methods: (1) crank-based integrated systems, which include spider, crank arm, and chainring setups, (2) hub-based integrated systems, (3) bottom-bracket sensors, (4) systems that measure \"opposing forces,\" and (5) pedal-based force sensors.$m22500$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m22501$nota-0018$m22501$, $m22502$nota-0010$m22502$, $m22503$complementa$m22503$, $m22504$explica por que o local de medição (cubo vs. manivela/pedal) gera a diferença sistemática de 5-10 W descrita em nota-0010$m22504$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m22505$nota-0018$m22505$, $m22506$nota-0011$m22506$, $m22507$complementa$m22507$, $m22508$explica por que medidores unilaterais (spider/crank-arm/bottom-bracket de um lado só) são vulneráveis ao viés de assimetria entre pernas de nota-0011$m22508$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22509$nota-0019$m22509$, $m22510$Training and Racing with a Power Meter.pdf$m22510$, $m22511$53$m22511$, $m22512$FTP is the highest power that a rider can maintain in a quasi–steady state without fatiguing. When power exceeds FTP, fatigue will occur much sooner (generally after approximately one hour in well-trained cyclists), whereas power just below FTP can be maintained considerably longer.$m22512$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22513$nota-0019$m22513$, $m22514$Training and Racing with a Power Meter.pdf$m22514$, $m22515$52$m22515$, $m22516$the exercise intensity at which lactate begins to accumulate in the blood, called lactate threshold... is a powerful predictor of performance.$m22516$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22517$nota-0022$m22517$, $m22518$Training and Racing with a Power Meter.pdf$m22518$, $m22519$61$m22519$, $m22520$TABLE 3.1 Power-Based Training Levels — Level | Description | % of FTP | % of FTHR | RPE | Typical Duration of Continuous Ride | Typical Duration of Interval Effort$m22520$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22521$nota-0022$m22521$, $m22522$Training and Racing with a Power Meter.pdf$m22522$, $m22523$62$m22523$, $m22524$Seven levels was the minimum number needed to represent the full range of physiological responses and to adequately describe the different types of training required and used to meet the demands of competitive cycling.$m22524$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22525$nota-0022$m22525$, $m22526$Manual treinamento.pdf$m22526$, $m22527$109$m22527$, $m22528$O sistema proposto por Andrew Coggan tornou-se um dos mais utilizados no ciclismo. Divide o treinamento em sete zonas: Zona 1 Recuperação ativa... Zona 7 Potência neuromuscular. Sprints máximos. Esse modelo tornou-se extremamente popular por sua simplicidade e aplicabilidade prática.$m22528$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m22529$nota-0022$m22529$, $m22530$nota-0019$m22530$, $m22531$pre-requisito$m22531$, $m22532$as zonas são definidas como percentual do FTP, definido na nota-0019$m22532$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m22533$nota-0022$m22533$, $m22534$nota-0024$m22534$, $m22535$complementa$m22535$, $m22536$a coluna RPE da Tabela 3.1 usa a escala Borg CR10 detalhada na nota-0024$m22536$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m22537$nota-0022$m22537$, $m22538$nota-0178$m22538$, $m22539$alternativa-a$m22539$, $m22540$o Manual treinamento.pdf (Fonte 2) propõe um modelo alternativo de 4 domínios fisiológicos (Moderado/Pesado/Severo/Extremo) baseado em LT1/LT2, descrevendo a mesma faixa de intensidades com granularidade e critério de corte diferentes$m22540$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22541$nota-0026$m22541$, $m22542$Training and Racing with a Power Meter.pdf$m22542$, $m22543$56$m22543$, $m22544$this approach consists of plotting the total work performed (in joules) during a series of relatively short (i.e., between 3 and 30 minutes), all-out efforts against their duration (in seconds), then fitting a straight line to the data points. The slope of this line is critical power.$m22544$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22545$nota-0026$m22545$, $m22546$Training and Racing with a Power Meter.pdf$m22546$, $m22547$57$m22547$, $m22548$Provided that you adhere to these guidelines... the value you obtain for CP will be essentially equal to FTP. On the other hand, if you calculate CP based on tests that are too short in duration, CP will be higher than FTP, and in fact will overestimate the true maximal metabolic steady-state intensity.$m22548$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m22549$nota-0026$m22549$, $m22550$nota-0019$m22550$, $m22551$alternativa-a$m22551$, $m22552$CP calculada corretamente é essencialmente igual ao FTP, mas é um modelo matemático diferente do teste de campo direto$m22552$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m22553$nota-0026$m22553$, $m22554$nota-0025$m22554$, $m22555$complementa$m22555$, $m22556$é um dos métodos alternativos de estimativa de FTP listados na nota-0025$m22556$)
